/** The `deployment.*` operations. */
export class DeploymentOperations {
  readonly #runner: Runner;

  /** @internal */
  constructor(runner: Runner) {
    this.#runner = runner;
  }

  /**
   * Reload agent definitions.
   *
   * Running agents use their current definition from their next turn. Sleeping agents use it when they wake. If you set agents, only those agents are updated. The node that handles the request also reloads its agent declarations, MCP servers and triggers.
   */
  reload(
    input: {
      /** Agent IDs, each listed once. Each includes its conversations. Defaults to every agent you can access. */
      agents?: string[] | undefined;
    } = {},
    options: CallOptions = {},
  ): Promise<Outputs["deployment.reload"]> {
    return this.#runner.call("deployment.reload", { ...input }, options);
  }

  /**
   * List nodes.
   */
  nodes(options: CallOptions = {}): Promise<Outputs["deployment.nodes"]> {
    return this.#runner.call("deployment.nodes", {}, options);
  }

  /**
   * Read resource use.
   *
   * Returns memory, CPU and process figures for each node, and the running agents that use the most memory. Measuring scheduler use takes 250 ms.
   */
  runtime(
    input: {
      /** The number of agents to return. Defaults to 20. */
      limit?: number | undefined;
    } = {},
    options: CallOptions = {},
  ): Promise<Outputs["deployment.runtime"]> {
    return this.#runner.call("deployment.runtime", { ...input }, options);
  }
}

/** Every operation but an agent's, by its namespace. */
export class Operations {
  /** The `agents.*` operations. */
  readonly agents: AgentsOperations;
  /** The `interrupts.*` operations. */
  readonly interrupts: InterruptsOperations;
  /** The `events.*` operations. */
  readonly events: EventsOperations;
  /** The `audit.*` operations. */
  readonly audit: AuditOperations;
  /** The `deployment.*` operations. */
  readonly deployment: DeploymentOperations;

  /** @internal */
  constructor(runner: Runner) {
    this.agents = new AgentsOperations(runner);
    this.interrupts = new InterruptsOperations(runner);
    this.events = new EventsOperations(runner);
    this.audit = new AuditOperations(runner);
    this.deployment = new DeploymentOperations(runner);
  }
}
